        // lang=c#
        const string expectedTypeMapper =
"""
// <auto-generated />
#nullable enable

namespace TestCase
{
    public partial class TestMapper :
        global::Morphant.ITypeMapper<global::TestCase.Source, int>
    {
        /// <inheritdoc/>
        protected override bool Supports(
            global::System.Type sourceType,
            global::System.Type destinationType) =>
                (sourceType == typeof(global::TestCase.Source) &&
                    destinationType == typeof(int)) ||
                base.Supports(sourceType, destinationType);

        /// <inheritdoc/>
        int global::Morphant.ITypeMapper<global::TestCase.Source, int>.Create(
            global::TestCase.Source? source,
            global::Morphant.Context.MappingContext context)
            => throw new global::Morphant.Exceptions.MappingConfigurationException(
                global::Morphant.Context.MappingOperation.Create,
                typeof(global::TestCase.Source),
                typeof(int),
                "ConstructorSelection does not apply to this destination type.");

        /// <inheritdoc/>
        int global::Morphant.ITypeMapper<global::TestCase.Source, int>.Update(
            global::TestCase.Source? source,
            int destination,
            global::Morphant.Context.MappingContext context)
            => throw new global::Morphant.Exceptions.MappingConfigurationException(
                global::Morphant.Context.MappingOperation.Update,
                typeof(global::TestCase.Source),
                typeof(int),
                "ConstructorSelection does not apply to this destination type.");
    }
}
""";

        var result = MappingSettingsDiagnosticsGeneratorTest.Run(
            OpaqueInapplicableSource,
            diagnosticOptions: new Dictionary<string, ReportDiagnostic>
            {
                ["MORPH0023"] = ReportDiagnostic.Suppress
            });

        Assert.Multiple(() =>
        {
            Assert.That(result.EffectiveDiagnostics, Is.Empty);
            Assert.That(
                result.GeneratedSources.Select(static generated =>
                    (generated.HintName,
                        generated.SourceText.ToString())),
                Is.EqualTo(new[]
                {
                    (
                        "Morphant.Generated.MappingExtension." +
                        "TestCase_Source__System_Int32.g.cs",
                        NormalizeExpected(expectedMappingExtension)),
                    (
                        "Morphant.Generated.TypeMapper." +
                        "TestCase_TestMapper.g.cs",
                        NormalizeExpected(expectedTypeMapper))
                }));
            Assert.That(result.CompilerWarningsAndErrors, Is.Empty);
        });
    }

    [TestCase("MORPH0021")]
    [TestCase("MORPH0022")]
    [TestCase("MORPH0023")]
    public void Suppression_and_severity_change_only_presentation(string id)
    {
        var source = id == "MORPH0023"
            ? InapplicableSource
            : InvalidMemberSource;
        IReadOnlyDictionary<string, string>? globalOptions =
            id == "MORPH0022"
                ? InvalidMemberProperty
                : null;

        if (id == "MORPH0022")
        {
            source = ValidSource;
        }

        var visible = MappingSettingsDiagnosticsGeneratorTest.Run(
            source,
            globalOptions: globalOptions);
        var suppressed = MappingSettingsDiagnosticsGeneratorTest.Run(
            source,
            diagnosticOptions: new Dictionary<string, ReportDiagnostic>
            {
                [id] = ReportDiagnostic.Suppress
            },
            globalOptions: globalOptions);
        var warning = MappingSettingsDiagnosticsGeneratorTest.Run(
            source,
            diagnosticOptions: new Dictionary<string, ReportDiagnostic>
            {
                [id] = ReportDiagnostic.Warn
            },
            globalOptions: globalOptions);

        Assert.Multiple(() =>
        {
            Assert.That(
                visible.Diagnostics.Select(static diagnostic => diagnostic.Id),
                Is.EqualTo(new[] { id }));
            Assert.That(suppressed.EffectiveDiagnostics, Is.Empty);
            Assert.That(
                warning.EffectiveDiagnostics.Single().Severity,
                Is.EqualTo(DiagnosticSeverity.Warning));
            Assert.That(Artifacts(suppressed), Is.EqualTo(Artifacts(visible)));
            Assert.That(Artifacts(warning), Is.EqualTo(Artifacts(visible)));
            Assert.That(visible.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(suppressed.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(warning.CompilerWarningsAndErrors, Is.Empty);
        });
    }

    [Test]
    public void One_driver_actualizes_CSharp_MSBuild_model_and_capability_changes()
    {
        var valid = MappingSettingsDiagnosticsGeneratorTest.Run(ValidSource);
        var invalidCSharp = MappingSettingsDiagnosticsGeneratorTest.Run(
            InvalidMemberSource,
            driver: valid.Driver);
        var restored = MappingSettingsDiagnosticsGeneratorTest.Run(
            ValidSource,
            driver: invalidCSharp.Driver);
        var manual = MappingSettingsDiagnosticsGeneratorTest.Run(
            InapplicableSource,
            driver: restored.Driver);
        var opaque = MappingSettingsDiagnosticsGeneratorTest.Run(
            OpaqueInapplicableSource,
            driver: manual.Driver);
        var invalidMsBuild = MappingSettingsDiagnosticsGeneratorTest.Run(
            ValidSource,
            globalOptions: InvalidMemberProperty,
            driver: opaque.Driver);
        var overriddenMsBuild = MappingSettingsDiagnosticsGeneratorTest.Run(
            ExplicitMemberSource,
            globalOptions: InvalidMemberProperty,
            driver: invalidMsBuild.Driver);
        var propertyRestored = MappingSettingsDiagnosticsGeneratorTest.Run(
            ValidSource,
            globalOptions: new Dictionary<string, string>
            {
                ["build_property.MorphantMemberSelection"] = "Auto"
            },
            driver: overriddenMsBuild.Driver);

        Assert.Multiple(() =>
        {
            Assert.That(valid.Diagnostics, Is.Empty);
            AssertDiagnostic(invalidCSharp, "MORPH0021", "invalid");
            Assert.That(restored.Diagnostics, Is.Empty);
            AssertDiagnostic(manual, "MORPH0023", "MemberSelection");
            AssertDiagnostic(opaque, "MORPH0023", "ConstructorSelection");
            Assert.That(
                invalidMsBuild.Diagnostics.Single().Id,
                Is.EqualTo("MORPH0022"));
            Assert.That(
                invalidMsBuild.Diagnostics.Single().Location,
                Is.EqualTo(Location.None));
            Assert.That(overriddenMsBuild.Diagnostics, Is.Empty);
            Assert.That(propertyRestored.Diagnostics, Is.Empty);
            Assert.That(valid.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(invalidCSharp.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(restored.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(manual.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(opaque.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(invalidMsBuild.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(overriddenMsBuild.CompilerWarningsAndErrors, Is.Empty);
            Assert.That(propertyRestored.CompilerWarningsAndErrors, Is.Empty);
        });
    }

    private static void AssertDiagnostic(
        MappingSettingsDiagnosticsGeneratorResult result,
        string id,
        string locationText)
    {
        var diagnostic = result.Diagnostics.Single();

        Assert.That(diagnostic.Id, Is.EqualTo(id));
        Assert.That(
            MappingSettingsDiagnosticsGeneratorTest.SourceText(
                diagnostic.Location),
            Is.EqualTo(locationText));
    }

    private static (string HintName, string Source)[] Artifacts(
        MappingSettingsDiagnosticsGeneratorResult result)
    {
        return result.GeneratedSources
            .OrderBy(static source => source.HintName, StringComparer.Ordinal)
            .Select(static source =>
                (source.HintName, source.SourceText.ToString()))
            .ToArray();
    }

    private static string NormalizeExpected(string source)
    {
        const string newLine = "\r\n";
        var normalized = source
            .Replace("\r\n", "\n")
            .Replace('\r', '\n')
            .Replace("\n", newLine);

        return normalized.EndsWith(newLine, StringComparison.Ordinal)
            ? normalized
            : normalized + newLine;
    }

    private static readonly IReadOnlyDictionary<string, string>
        InvalidMemberProperty = new Dictionary<string, string>
        {
            ["build_property.MorphantMemberSelection"] = "Unexpected"
        };

